// data/publications.ts
export type Pub = {
  title: string;
  authors: string[];          // "David Barron" gets bolded automatically
  venue: string;              // "UIST 2026"
  year: number;
  status?: "accepted" | "under review" | "preprint";
  links?: { pdf?: string; video?: string; code?: string; doi?: string };
  award?: string;
};

export const pubs: Pub[] = [
  {
    title: "TutorTrace: …",
    authors: ["David Barron", "…", "Yan Chen"],
    venue: "UIST 2026",
    year: 2026,
    status: "accepted",
    links: { pdf: "/papers/tutortrace-uist26.pdf" },
  },
];
