// components/Publications.tsx
import { pubs } from "@/data/publications";

const ME = "David Barron";

export default function Publications() {
  return (
    <section className="mt-12">
      <h2 className="text-sm font-semibold uppercase tracking-wide text-neutral-500">Publications</h2>
      <ul className="mt-4 space-y-5">
        {pubs.sort((a, b) => b.year - a.year).map((p) => (
          <li key={p.title}>
            <p className="font-medium">{p.title}</p>
            <p className="text-sm text-neutral-600">
              {p.authors.map((a, i) => (
                <span key={a}>
                  {a === ME ? <strong>{a}</strong> : a}
                  {i < p.authors.length - 1 ? ", " : ""}
                </span>
              ))}
            </p>
            <p className="text-sm">
              <span className="italic">{p.venue}</span>
              {p.status && p.status !== "accepted" && <span className="ml-2 text-neutral-500">({p.status})</span>}
              {p.links &&
                Object.entries(p.links).map(([k, v]) => (
                  <a key={k} href={v} className="ml-3 underline underline-offset-2">{k}</a>
                ))}
            </p>
          </li>
        ))}
      </ul>
    </section>
  );
}
